class Compte:
    def __init__(self, solde=0.0):
        if solde < 0:
            raise ValueError("solde négatif")
        self._solde = solde

    @property
    def solde(self):
        return self._solde

    def retirer(self, montant):
        if montant <= 0 or montant > self._solde:
            raise ValueError("montant invalide")
        self._solde -= montant

from dataclasses import dataclass, field

@dataclass(frozen=True)
class Article:
    nom: str
    prix: float

@dataclass
class Panier:
    articles: list[Article] = field(default_factory=list)

    def total(self) -> float:
        return sum(a.prix for a in self.articles)
